(function(){'use strict';var sourceFilesData=[];var categoryDict={};var channelsCurrentPage=1;var channelsPageSize=100;var channelsPageData=[];var channelsTotalCount=0;var currentExpandedId=null;var channelsSearchTimer=null;var editingChannelIdx=-1;var editingChannelName='';var QUICK_UAS=[{label:'Chrome',value:'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'},{label:'iPhone',value:'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1'},{label:'VLC',value:'VLC/3.0.18 LibVLC/3.0.18'},{label:'okhttp',value:'okhttp/4.9.3'}];var DIM_ORDER=['content','region','language','quality','media_type','genre'];var DIM_LABELS={content:'内容分类',region:'地区',language:'语言',quality:'画质',media_type:'媒体类型',genre:'类型'};var METHOD_LABELS={raw:'raw',api:'API',proxy:'代理',mirror:'镜像'};var METHOD_FULL_LABELS={raw:'raw.githubusercontent.com（默认）',api:'GitHub API',proxy:'SOCKS/HTTP代理',mirror:'代理网站'};function esc(s){return LSM.escapeHtml(s);}
function truncateText(text,maxLen){if(!text)return'';if(text.length>maxLen)return text.substring(0,maxLen-3)+'...';return text;}
function errText(e,fallback){return(e&&e.message)?e.message:(fallback||'网络错误');}
function findFile(fileId){for(var i=0;i<sourceFilesData.length;i++){if(sourceFilesData[i].id===fileId)return sourceFilesData[i];}
return null;}
function loadCategoryDictionary(){fetch('/api/category-dictionary',{credentials:'same-origin'}).then(function(r){return r.json();}).then(function(data){categoryDict=data.raw||{};}).catch(function(){});}
function renderSourceFiles(data){var files=data.files||[];sourceFilesData=files;var tbody=document.getElementById('source-files-tbody');var totalChannels=0;for(var i=0;i<files.length;i++)totalChannels+=files[i].channel_count||0;var el=document.getElementById('source-stats-info');if(el)el.textContent='源文件: '+files.length+' 个 | 频道: '+totalChannels+' 个';if(files.length===0){tbody.innerHTML='<tr><td colspan="7" class="empty-state">暂无源文件，点击"添加源文件"开始</td></tr>';return;}
var html='';for(var i=0;i<files.length;i++){var f=files[i];var typeLabel='',typeClass='';if(f.type==='online'){typeLabel='在线URL';typeClass='badge badge-blue';}else if(f.type==='github'){var method=f.download_method||'raw';typeLabel='GitHub <span class="badge badge-gray text-sm" data-action="change-method" data-file-id="'+esc(f.id)+'" data-method="'+esc(method)+'" title="'+esc(f.download_method_label||'raw.githubusercontent.com')+' — 点击切换" style="cursor:pointer">#'+esc(METHOD_LABELS[method]||method)+'</span>';typeClass='badge badge-yellow';}else{typeLabel='本地';typeClass='badge badge-green';}
var statusLabel='',statusClass='';if(f.file_status==='downloaded'){statusLabel='已下载';if(f.discovered_count>0)statusLabel+=' '+f.matched_count+'/'+f.discovered_count;statusClass='badge badge-green';}else if(f.file_status==='partial'){statusLabel='部分下载 '+f.matched_count+'/'+f.discovered_count;statusClass='badge badge-yellow';}else if(f.file_status==='not_downloaded'){statusLabel='未下载 '+f.matched_count+'/'+f.discovered_count;statusClass='badge badge-red';}else if(f.file_status==='github_pending'){statusLabel='待展开';statusClass='badge badge-gray';}else if(f.file_status==='local_exists'){statusLabel='存在';statusClass='badge badge-green';}else if(f.file_status==='local_pending'){statusLabel='待生成';statusClass='badge badge-gray';}else if(f.file_status==='local_missing'){statusLabel='路径缺失';statusClass='badge badge-red';}else{statusLabel='未知';statusClass='badge badge-gray';}
var chCount=f.channel_count>0?f.channel_count:'-';var addrDisplay=truncateText(f.url_or_path||'',60);var ua=f.ua_settings||{};var uaBadge='';if(ua.enabled&&ua.ua_value){var uaShort=truncateText(ua.ua_value,25);var uaPosLabel=ua.ua_position==='url'?'URL参数':'属性';uaBadge='<span class="badge badge-blue text-sm" data-action="edit-file-ua" data-file-id="'+esc(f.id)+'" title="'+esc(ua.ua_value)+' ('+uaPosLabel+')" style="cursor:pointer">UA: '+esc(uaShort)+'</span>';}else{uaBadge='<span class="badge badge-gray text-sm" data-action="edit-file-ua" data-file-id="'+esc(f.id)+'" style="cursor:pointer">未设置</span>';}
html+='<tr id="file-row-'+esc(f.id)+'">';html+='<td>'+esc(f.name||'')+'</td>';html+='<td><span class="'+typeClass+'">'+typeLabel+'</span></td>';html+='<td class="url-cell" title="'+esc(f.url_or_path||'')+'">'+esc(addrDisplay)+'<button type="button" class="copy-btn" data-copy="'+esc(f.url_or_path||'')+'" aria-label="复制地址" title="复制地址">'+LSM.icon('copy')+'</button></td>';html+='<td><span class="'+statusClass+'">'+statusLabel+'</span></td>';html+='<td class="text-center">'+chCount+'</td>';html+='<td>'+uaBadge+'</td>';html+='<td class="actions">';html+='<button class="btn btn-sm btn-outline" data-action="expand" data-file-id="'+esc(f.id)+'">展开</button>';if(window.IS_ADMIN){html+='<button class="btn btn-sm btn-danger" data-action="delete-file" data-file-id="'+esc(f.id)+'">删除</button>';}
html+='</td></tr>';}
tbody.innerHTML=html;}
function loadSourceFiles(){fetch('/api/source-files',{credentials:'same-origin'}).then(function(r){return r.json();}).then(function(data){renderSourceFiles(data);}).catch(function(e){document.getElementById('source-files-tbody').innerHTML='<tr><td colspan="7" class="alert alert-error">加载失败: '+esc(errText(e))+'</td></tr>';});}
function collectAllSources(){var btn=document.getElementById('btn-collect');LSM.setBtnLoading(btn,true,'采集中...');LSM.ensureCsrfToken().then(function(csrfToken){return fetch('/api/sources/collect',{method:'POST',headers:{'X-CSRF-Token':csrfToken},credentials:'same-origin'});}).then(function(r){return r.json();}).then(function(data){LSM.showToast(data.message||'源采集已启动','info');setTimeout(function(){loadSourceFiles();LSM.setBtnLoading(btn,false);},5000);}).catch(function(e){LSM.showToast('采集请求失败: '+errText(e),'error');LSM.setBtnLoading(btn,false);});}
function expandChannels(fileId){if(currentExpandedId===fileId){closeChannels();return;}
currentExpandedId=fileId;channelsCurrentPage=1;var searchInput=document.getElementById('channels-search');if(searchInput)searchInput.value='';var rows=document.querySelectorAll('#source-files-tbody tr');rows.forEach(function(r){r.classList.remove('row-active');});var row=document.getElementById('file-row-'+fileId);if(row)row.classList.add('row-active');var card=document.getElementById('channels-card');card.classList.remove('hidden');var tbody=document.getElementById('channels-tbody');tbody.innerHTML='<tr><td colspan="6" class="loading">解析中...</td></tr>';document.getElementById('channels-info').textContent='';document.getElementById('channels-pagination').innerHTML='';var fileObj=findFile(fileId);document.getElementById('channels-title').textContent='频道列表 - '+(fileObj?fileObj.name:'');fetchChannelsPage();}
function fetchChannelsPage(){var fileId=currentExpandedId;if(!fileId)return;var searchInput=document.getElementById('channels-search');var search=searchInput?searchInput.value.trim():'';var url='/api/source-files/'+fileId+'/channels?page='+channelsCurrentPage+'&size='+channelsPageSize;if(search)url+='&search='+encodeURIComponent(search);var tbody=document.getElementById('channels-tbody');tbody.innerHTML='<tr><td colspan="6" class="loading">加载中...</td></tr>';fetch(url,{credentials:'same-origin'}).then(function(r){return r.json();}).then(function(data){channelsPageData=data.channels||[];channelsTotalCount=data.total||0;if(data.message){document.getElementById('channels-info').textContent=data.message;}else{var infoText='共 '+data.total+' 个频道';if(data.unfiltered_total&&data.unfiltered_total!==data.total){infoText+='（筛选自 '+data.unfiltered_total+' 个）';}
infoText+='，第 '+data.page+'/'+(Math.ceil(data.total/channelsPageSize)||1)+' 页';document.getElementById('channels-info').textContent=infoText;}
renderChannelsPage();}).catch(function(e){tbody.innerHTML='<tr><td colspan="6" class="alert alert-error">加载失败: '+esc(errText(e))+'</td></tr>';});}
function channelsSearchDebounced(){if(channelsSearchTimer)clearTimeout(channelsSearchTimer);channelsSearchTimer=setTimeout(function(){channelsCurrentPage=1;fetchChannelsPage();},400);}
function closeChannels(){document.getElementById('channels-card').classList.add('hidden');currentExpandedId=null;var rows=document.querySelectorAll('#source-files-tbody tr');rows.forEach(function(r){r.classList.remove('row-active');});}
function renderChannelsPage(){var pageData=channelsPageData;var total=channelsTotalCount;var totalPages=Math.ceil(total/channelsPageSize)||1;var tbody=document.getElementById('channels-tbody');if(pageData.length===0){tbody.innerHTML='<tr><td colspan="6" class="empty-state">无频道数据</td></tr>';}else{var html='';for(var i=0;i<pageData.length;i++){var ch=pageData[i];var chName=ch.name||'';var chIdx=i;var mapping=ch.existing_mapping;var hasManual=mapping&&mapping.is_manual==1;var catDisplay='';var catClass='auto';if(mapping&&hasManual){var parts=[];if(mapping.content&&mapping.content!=='其他频道'){parts=parts.concat(mapping.content.split(','));}
if(mapping.region&&mapping.region!=='未知')parts.push(mapping.region);if(mapping.quality&&mapping.quality!=='未知')parts.push(mapping.quality);catDisplay=parts.length>0?parts.join(' · '):'已设置';catClass='manual';}else if(mapping&&!hasManual){catDisplay=mapping.content||ch.category||'-';catClass='auto';}else{catDisplay=ch.category||'-';catClass='auto';}
var uaDisplay='';var uaClass='auto';if(ch.ua_override){uaDisplay=truncateText(ch.user_agent||'',20);uaClass='manual';}else if(ch.user_agent){uaDisplay=truncateText(ch.user_agent,20);uaClass='auto';}else{uaDisplay='-';}
html+='<tr id="ch-row-'+chIdx+'">';html+='<td>'+esc(chName)+'</td>';html+='<td class="url-cell" title="'+esc(ch.url||'')+'">'+esc(truncateText(ch.url||'',60))+'<button type="button" class="copy-btn" data-copy="'+esc(ch.url||'')+'" aria-label="复制地址" title="复制地址">'+LSM.icon('copy')+'</button></td>';html+='<td>'+esc(ch.group||'-')+'</td>';html+='<td><span class="category-badge '+catClass+'" data-action="edit-category" data-ch-idx="'+chIdx+'" title="点击修改分类">'+esc(catDisplay)+'</span></td>';html+='<td><span class="category-badge '+uaClass+'" data-action="edit-channel-ua" data-ch-idx="'+chIdx+'" title="点击配置 UA">'+esc(uaDisplay)+'</span></td>';html+='<td class="actions"><button class="btn btn-sm btn-outline" data-action="edit-category" data-ch-idx="'+chIdx+'">分类</button></td>';html+='</tr>';}
tbody.innerHTML=html;}
var container=document.getElementById('channels-pagination');if(totalPages<=1){container.innerHTML='';return;}
LSM.renderPagination(container,{page:channelsCurrentPage,totalPages:totalPages,total:total,onChange:function(page){channelsCurrentPage=page;fetchChannelsPage();}});}
function showCategoryEditor(chIdx,chName){var ch=channelsPageData[chIdx];if(!ch)return;editingChannelIdx=chIdx;editingChannelName=chName;var currentMapping=ch.existing_mapping||{};var form=document.createElement('div');form.className='prompt-field';DIM_ORDER.forEach(function(dim){var opts=categoryDict[dim]||[];var curVal=currentMapping[dim]||'';var curVals=curVal?curVal.split(','):[];var isMulti=(dim==='content');var row=document.createElement('div');row.className='form-group';var label=document.createElement('label');label.setAttribute('for','cat-dim-'+dim);label.textContent=DIM_LABELS[dim]||dim;if(isMulti){var hint=document.createElement('small');hint.className='form-help';hint.textContent='（可多选：按住 Ctrl/Cmd 选多个时输出会复制频道到各分组）';label.appendChild(hint);}
row.appendChild(label);var select=document.createElement('select');select.id='cat-dim-'+dim;select.className='form-input';if(isMulti){select.multiple=true;select.size=5;}else{var autoOpt=document.createElement('option');autoOpt.value='';autoOpt.textContent='— 自动 —';select.appendChild(autoOpt);}
opts.forEach(function(o){var opt=document.createElement('option');opt.value=o.value;opt.textContent=o.label||o.value;var selected=isMulti?(curVals.indexOf(o.value)>=0):(o.value===curVal);opt.selected=selected;select.appendChild(opt);});row.appendChild(select);form.appendChild(row);});LSM.showModal({title:'分类编辑 — '+chName,content:form,width:'480px',buttons:[{text:'取消',action:'cancel',type:'outline'},{text:'清除手动分类',action:'clear',type:'danger',onClick:function(){LSM.confirm('确认清除 "'+editingChannelName+'" 的手动分类？','确认清除').then(function(ok){if(ok)clearChannelCategory();});return false;}},{text:'保存',action:'confirm',type:'primary',onClick:function(){saveChannelCategory();return false;}}]});}
function collectCategoryForm(){var categories={};DIM_ORDER.forEach(function(dim){var el=document.getElementById('cat-dim-'+dim);if(!el)return;if(dim==='content'&&el.multiple){var selected=[];for(var i=0;i<el.options.length;i++){if(el.options[i].selected&&el.options[i].value)selected.push(el.options[i].value);}
if(selected.length>0)categories[dim]=selected.join(',');}else if(el.value){categories[dim]=el.value;}});return categories;}
function saveChannelCategory(){if(!editingChannelName)return;var categories=collectCategoryForm();LSM.ensureCsrfToken().then(function(csrfToken){return fetch('/api/channel-mapping/'+encodeURIComponent(editingChannelName),{method:'PUT',headers:{'Content-Type':'application/json','X-CSRF-Token':csrfToken},credentials:'same-origin',body:JSON.stringify(categories)});}).then(function(r){return r.json().then(function(d){return{ok:r.ok,data:d};});}).then(function(res){if(!res.ok){LSM.showToast(res.data.detail||'保存失败','error');return;}
LSM.showToast('分类已保存: '+editingChannelName,'success');if(channelsPageData[editingChannelIdx]){channelsPageData[editingChannelIdx].existing_mapping=Object.assign({is_manual:1},res.data.categories||categories);}
LSM.closeTopModal();renderChannelsPage();}).catch(function(e){LSM.showToast('保存失败: '+errText(e),'error');});}
function clearChannelCategory(){if(!editingChannelName)return;LSM.ensureCsrfToken().then(function(csrfToken){return fetch('/api/channel-mapping/'+encodeURIComponent(editingChannelName),{method:'DELETE',headers:{'X-CSRF-Token':csrfToken},credentials:'same-origin'});}).then(function(r){return r.json().then(function(d){return{ok:r.ok,data:d};});}).then(function(res){if(!res.ok){LSM.showToast(res.data.detail||'清除失败','error');return;}
LSM.showToast('手动分类已清除','success');if(channelsPageData[editingChannelIdx]){channelsPageData[editingChannelIdx].existing_mapping=null;}
LSM.closeTopModal();renderChannelsPage();}).catch(function(e){LSM.showToast('清除失败: '+errText(e),'error');});}
function showFileUaEditor(fileId){var fileObj=findFile(fileId);if(!fileObj)return;var ua=fileObj.ua_settings||{};var enabled=ua.enabled||false;var uaValue=ua.ua_value||'';var uaPosition=ua.ua_position||'extinf';var form=document.createElement('div');form.className='prompt-field';var enableRow=document.createElement('div');enableRow.className='form-group';var enableLabel=document.createElement('label');enableLabel.className='toggle';var enableInput=document.createElement('input');enableInput.type='checkbox';enableInput.id='ua-enabled';enableInput.checked=enabled;var enableSlider=document.createElement('span');enableSlider.className='toggle-slider';var enableText=document.createElement('span');enableText.className='toggle-label';enableText.textContent='启用 User-Agent';enableLabel.appendChild(enableInput);enableLabel.appendChild(enableSlider);enableLabel.appendChild(enableText);enableRow.appendChild(enableLabel);form.appendChild(enableRow);var posRow=document.createElement('div');posRow.className='form-group';var posLabel=document.createElement('label');posLabel.setAttribute('for','ua-position');posLabel.textContent='输出位置';var posSelect=document.createElement('select');posSelect.id='ua-position';posSelect.className='form-select';posSelect.innerHTML='<option value="extinf"'+(uaPosition==='extinf'?' selected':'')+'>EXTINF 属性 (user-agent="...")</option>'+'<option value="url"'+(uaPosition==='url'?' selected':'')+'>URL 参数 (|User-Agent=...)</option>';posRow.appendChild(posLabel);posRow.appendChild(posSelect);form.appendChild(posRow);var valueRow=document.createElement('div');valueRow.className='form-group';var valueLabel=document.createElement('label');valueLabel.setAttribute('for','ua-value');valueLabel.textContent='UA 值';var valueInput=document.createElement('textarea');valueInput.id='ua-value';valueInput.className='form-input form-textarea';valueInput.placeholder='Mozilla/5.0 (Windows NT 10.0; Win64; x64) ...';valueInput.textContent=uaValue;valueRow.appendChild(valueLabel);valueRow.appendChild(valueInput);form.appendChild(valueRow);var quickRow=document.createElement('div');quickRow.className='form-group';var quickTitle=document.createElement('span');quickTitle.className='form-help';quickTitle.textContent='快捷:';quickRow.appendChild(quickTitle);var quickGroup=document.createElement('div');quickGroup.className='quick-actions mt-4';QUICK_UAS.forEach(function(q){var btn=document.createElement('button');btn.type='button';btn.className='btn btn-sm btn-ghost';btn.textContent=q.label;btn.addEventListener('click',function(){valueInput.value=q.value;valueInput.focus();});quickGroup.appendChild(btn);});quickRow.appendChild(quickGroup);form.appendChild(quickRow);var help=document.createElement('div');help.className='form-help';help.textContent='启用后，该文件中的所有视频源默认使用此 UA。每个视频源仍可单独配置 UA 覆盖此设置。';form.appendChild(help);function refreshEnabled(){posSelect.disabled=!enableInput.checked;valueInput.disabled=!enableInput.checked;}
enableInput.addEventListener('change',refreshEnabled);var buttons=[{text:'取消',action:'cancel',type:'outline'},{text:'保存',action:'confirm',type:'primary',onClick:function(){saveFileUa(fileId,enableInput.checked,valueInput.value.trim(),posSelect.value);return false;}}];if(enabled){buttons.splice(1,0,{text:'清除',action:'clear',type:'danger',onClick:function(){LSM.confirm('确认清除该源文件的 UA 配置？','确认清除').then(function(ok){if(ok)clearFileUa(fileId);});return false;}});}
LSM.showModal({title:'UA 配置 — '+(fileObj.name||''),content:form,width:'480px',buttons:buttons,onClose:refreshEnabled});refreshEnabled();}
function saveFileUa(fileId,enabled,uaValue,uaPosition){if(enabled&&!uaValue){LSM.showToast('启用 UA 时必须填写 UA 值','error');return;}
LSM.ensureCsrfToken().then(function(csrfToken){return fetch('/api/source-files/'+fileId+'/ua',{method:'PUT',headers:{'Content-Type':'application/json','X-CSRF-Token':csrfToken},credentials:'same-origin',body:JSON.stringify({enabled:enabled,ua_value:uaValue,ua_position:uaPosition})});}).then(function(r){return r.json().then(function(d){return{ok:r.ok,data:d};});}).then(function(res){if(!res.ok){LSM.showToast(res.data.detail||'保存失败','error');return;}
LSM.showToast(res.data.message||'UA 设置已保存','success');LSM.closeTopModal();loadSourceFiles();}).catch(function(e){LSM.showToast('保存失败: '+errText(e),'error');});}
function clearFileUa(fileId){LSM.ensureCsrfToken().then(function(csrfToken){return fetch('/api/source-files/'+fileId+'/ua',{method:'DELETE',headers:{'X-CSRF-Token':csrfToken},credentials:'same-origin'});}).then(function(r){return r.json().then(function(d){return{ok:r.ok,data:d};});}).then(function(res){if(!res.ok){LSM.showToast(res.data.detail||'清除失败','error');return;}
LSM.showToast(res.data.message||'UA 设置已清除','success');LSM.closeTopModal();loadSourceFiles();}).catch(function(e){LSM.showToast('清除失败: '+errText(e),'error');});}
function showChannelUaEditor(chIdx){var ch=channelsPageData[chIdx];if(!ch)return;var isOverride=ch.ua_override||false;var uaValue=ch.user_agent||'';var uaPosition=ch.ua_position||'extinf';var form=document.createElement('div');form.className='prompt-field';var note=document.createElement('div');note.className='form-help';if(isOverride){note.textContent='当前为频道级覆盖';note.classList.add('text-warning');}else if(ch.user_agent){note.textContent='当前 UA 来自文件级或源文件内置，设置后将覆盖为频道级';}else{note.textContent='当前无 UA，设置后将为此频道单独配置';}
form.appendChild(note);var posRow=document.createElement('div');posRow.className='form-group';var posLabel=document.createElement('label');posLabel.setAttribute('for','ch-ua-position');posLabel.textContent='输出位置';var posSelect=document.createElement('select');posSelect.id='ch-ua-position';posSelect.className='form-select';posSelect.innerHTML='<option value="extinf"'+(uaPosition==='extinf'?' selected':'')+'>EXTINF 属性</option>'+'<option value="url"'+(uaPosition==='url'?' selected':'')+'>URL 参数</option>';posRow.appendChild(posLabel);posRow.appendChild(posSelect);form.appendChild(posRow);var valueRow=document.createElement('div');valueRow.className='form-group';var valueLabel=document.createElement('label');valueLabel.setAttribute('for','ch-ua-value');valueLabel.textContent='UA 值';var valueInput=document.createElement('textarea');valueInput.id='ch-ua-value';valueInput.className='form-input form-textarea';valueInput.placeholder='留空清除覆盖，恢复文件级 UA';valueInput.textContent=uaValue;valueRow.appendChild(valueLabel);valueRow.appendChild(valueInput);form.appendChild(valueRow);var quickGroup=document.createElement('div');quickGroup.className='quick-actions';QUICK_UAS.forEach(function(q){var btn=document.createElement('button');btn.type='button';btn.className='btn btn-sm btn-ghost';btn.textContent=q.label;btn.addEventListener('click',function(){valueInput.value=q.value;valueInput.focus();});quickGroup.appendChild(btn);});form.appendChild(quickGroup);var buttons=[{text:'取消',action:'cancel',type:'outline'},{text:'保存',action:'confirm',type:'primary',onClick:function(){saveChannelUa(chIdx,valueInput.value.trim(),posSelect.value);return false;}}];if(isOverride){buttons.splice(1,0,{text:'清除覆盖',action:'clear',type:'danger',onClick:function(){clearChannelUa(chIdx);return false;}});}
LSM.showModal({title:'频道 UA — '+(ch.name||''),content:form,width:'480px',buttons:buttons});}
function saveChannelUa(chIdx,uaValue,uaPosition){var ch=channelsPageData[chIdx];if(!ch)return;if(!uaValue){if(ch.ua_override){clearChannelUa(chIdx);}else{LSM.showToast('请输入 UA 值','error');}
return;}
var fileId=currentExpandedId;LSM.ensureCsrfToken().then(function(csrfToken){return fetch('/api/source-files/'+fileId+'/channel-ua',{method:'PUT',headers:{'Content-Type':'application/json','X-CSRF-Token':csrfToken},credentials:'same-origin',body:JSON.stringify({url:ch.url,ua_value:uaValue,ua_position:uaPosition})});}).then(function(r){return r.json().then(function(d){return{ok:r.ok,data:d};});}).then(function(res){if(!res.ok){LSM.showToast(res.data.detail||'保存失败','error');return;}
LSM.showToast(res.data.message||'频道 UA 已保存','success');channelsPageData[chIdx].user_agent=uaValue;channelsPageData[chIdx].ua_position=uaPosition;channelsPageData[chIdx].ua_override=true;LSM.closeTopModal();renderChannelsPage();}).catch(function(e){LSM.showToast('保存失败: '+errText(e),'error');});}
function clearChannelUa(chIdx){var ch=channelsPageData[chIdx];if(!ch)return;var fileId=currentExpandedId;LSM.ensureCsrfToken().then(function(csrfToken){return fetch('/api/source-files/'+fileId+'/channel-ua?url='+encodeURIComponent(ch.url),{method:'DELETE',headers:{'X-CSRF-Token':csrfToken},credentials:'same-origin'});}).then(function(r){return r.json().then(function(d){return{ok:r.ok,data:d};});}).then(function(res){if(!res.ok){LSM.showToast(res.data.detail||'清除失败','error');return;}
LSM.showToast(res.data.message||'频道 UA 覆盖已删除','success');LSM.closeTopModal();expandChannels(currentExpandedId);}).catch(function(e){LSM.showToast('清除失败: '+errText(e),'error');});}
function deleteSourceFile(fileId){var fileObj=findFile(fileId);var fileName=fileObj?fileObj.name:fileId;LSM.confirm('确认删除源文件 "'+fileName+'"？\n\n'+'在线源：删除已下载的文件和配置\n'+'GitHub源：移除配置（已下载文件保留）\n'+'本地源：移除配置（原文件不删除）','删除源文件').then(function(confirmed){if(!confirmed)return;LSM.ensureCsrfToken().then(function(csrfToken){return fetch('/api/source-files/'+fileId,{method:'DELETE',headers:{'X-CSRF-Token':csrfToken},credentials:'same-origin'});}).then(function(r){return r.json().then(function(d){return{ok:r.ok,data:d};});}).then(function(res){if(!res.ok){LSM.showToast(res.data.detail||'删除失败','error');return;}
LSM.showToast(res.data.message||'删除成功','success');if(currentExpandedId===fileId)closeChannels();loadSourceFiles();}).catch(function(e){LSM.showToast('删除失败: '+errText(e),'error');});});}
function changeDownloadMethod(fileId,currentMethod){LSM.promptChoice({title:'选择下载方式',label:'当前: '+(METHOD_FULL_LABELS[currentMethod]||currentMethod),value:currentMethod,choices:[{value:'raw',label:'raw.githubusercontent.com',description:'默认方式，直接拉取原始文件'},{value:'api',label:'GitHub API',description:'有速率限制（未配置 Token 60次/时）'},{value:'proxy',label:'SOCKS/HTTP 代理',description:'通过代理访问 GitHub'},{value:'mirror',label:'代理网站',description:'如 ghproxy.com 等镜像加速'}]}).then(function(method){if(!method||!['raw','api','proxy','mirror'].includes(method))return;LSM.ensureCsrfToken().then(function(csrfToken){return fetch('/api/source-files/'+fileId,{method:'PUT',headers:{'Content-Type':'application/json','X-CSRF-Token':csrfToken},credentials:'same-origin',body:JSON.stringify({download_method:method})});}).then(function(r){return r.json().then(function(d){return{ok:r.ok,data:d};});}).then(function(res){if(!res.ok){LSM.showToast(res.data.detail||'更新失败','error');return;}
LSM.showToast(res.data.message||'下载方式已更新','success');loadSourceFiles();}).catch(function(e){LSM.showToast('更新失败: '+errText(e),'error');});});}
var modalReturnFocus=null;function openAddFileModal(){var modal=document.getElementById('add-file-modal');modalReturnFocus=document.activeElement;modal.classList.add('is-open');var first=modal.querySelector('input:not([disabled]), select, textarea');if(first)first.focus();}
function closeAddFileModal(){var modal=document.getElementById('add-file-modal');modal.classList.remove('is-open');if(modalReturnFocus&&typeof modalReturnFocus.focus==='function'){modalReturnFocus.focus();}
modalReturnFocus=null;document.getElementById('add-file-result').innerHTML='';}
function onTypeChange(){var type=document.getElementById('file-type').value;var label=document.getElementById('value-label');var input=document.getElementById('file-value');var help=document.getElementById('value-help');var methodGroup=document.getElementById('method-group');if(type==='online'){label.textContent='文件 URL';input.placeholder='https://example.com/iptv.m3u';help.textContent='包含多个视频源的 m3u/txt 文件 URL，添加后自动下载';methodGroup.classList.add('hidden');}else if(type==='github'){label.textContent='GitHub 仓库';input.placeholder='owner/repo 或 owner/repo/branch';help.textContent='格式: owner/repo、owner/repo/branch、owner/repo/branch/path。添加后需点击"采集所有源"下载';methodGroup.classList.remove('hidden');}else if(type==='local'){label.textContent='本地路径';input.placeholder='./config/sources/myfile.m3u';help.textContent='相对于项目根目录的文件或目录路径，目录下所有 m3u/txt 文件都会被解析';methodGroup.classList.add('hidden');}}
function submitAddFile(){var type=document.getElementById('file-type').value;var value=document.getElementById('file-value').value.trim();var resultDiv=document.getElementById('add-file-result');if(!value){resultDiv.innerHTML='<div class="alert alert-error">地址不能为空</div>';return;}
resultDiv.innerHTML='<div class="alert alert-info">处理中...</div>';var body={type:type,value:value};if(type==='github'){body.download_method=document.getElementById('download-method').value;}
LSM.ensureCsrfToken().then(function(csrfToken){return fetch('/api/source-files',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrfToken},credentials:'same-origin',body:JSON.stringify(body)});}).then(function(r){return r.json().then(function(d){return{ok:r.ok,data:d};});}).then(function(res){if(res.ok||res.data.status==='created'||res.data.status==='exists'){closeAddFileModal();LSM.showToast(res.data.message||'添加成功',res.data.status==='exists'?'info':'success');loadSourceFiles();}else{resultDiv.innerHTML='<div class="alert alert-error">'+esc(res.data.detail||res.data.message||'操作失败')+'</div>';}}).catch(function(e){resultDiv.innerHTML='<div class="alert alert-error">'+esc(errText(e))+'</div>';});}
function bindTableEvents(){var filesTbody=document.getElementById('source-files-tbody');if(filesTbody){filesTbody.addEventListener('click',function(e){var copyBtn=e.target.closest('[data-copy]');if(copyBtn){copyText(copyBtn.dataset.copy);return;}
var btn=e.target.closest('[data-action]');if(!btn)return;var action=btn.dataset.action;if(action==='expand'){expandChannels(btn.dataset.fileId);}else if(action==='delete-file'){deleteSourceFile(btn.dataset.fileId);}else if(action==='edit-file-ua'){showFileUaEditor(btn.dataset.fileId);}else if(action==='change-method'){changeDownloadMethod(btn.dataset.fileId,btn.dataset.method);}});}
var channelsTbody=document.getElementById('channels-tbody');if(channelsTbody){channelsTbody.addEventListener('click',function(e){var copyBtn=e.target.closest('[data-copy]');if(copyBtn){copyText(copyBtn.dataset.copy);return;}
var btn=e.target.closest('[data-action]');if(!btn)return;var action=btn.dataset.action;var chIdx=parseInt(btn.dataset.chIdx,10);if(action==='edit-category'){var ch=channelsPageData[chIdx];showCategoryEditor(chIdx,ch?(ch.name||''):'');}else if(action==='edit-channel-ua'){showChannelUaEditor(chIdx);}});}}
function copyText(text){if(!text)return;function done(){LSM.showToast('已复制到剪贴板','success');}
function fail(){LSM.showToast('复制失败，请手动复制','warning');}
if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(text).then(done).catch(fail);}else{var ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();var ok=false;try{ok=document.execCommand('copy');}catch(e){ok=false;}
document.body.removeChild(ta);if(ok){done();}else{fail();}}}
document.addEventListener('DOMContentLoaded',function(){var btnAddFile=document.getElementById('btn-add-file');if(btnAddFile)btnAddFile.addEventListener('click',openAddFileModal);var btnCollect=document.getElementById('btn-collect');if(btnCollect)btnCollect.addEventListener('click',collectAllSources);var btnRefresh=document.getElementById('btn-refresh-sources');if(btnRefresh)btnRefresh.addEventListener('click',loadSourceFiles);var btnCloseChannels=document.getElementById('btn-close-channels');if(btnCloseChannels)btnCloseChannels.addEventListener('click',closeChannels);var searchInput=document.getElementById('channels-search');if(searchInput)searchInput.addEventListener('input',channelsSearchDebounced);var addModal=document.getElementById('add-file-modal');if(addModal){addModal.querySelectorAll('[data-modal-close]').forEach(function(el){el.addEventListener('click',closeAddFileModal);});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&addModal.classList.contains('is-open')){closeAddFileModal();}});}
var fileType=document.getElementById('file-type');if(fileType)fileType.addEventListener('change',onTypeChange);var btnSubmitAdd=document.getElementById('btn-submit-add-file');if(btnSubmitAdd)btnSubmitAdd.addEventListener('click',submitAddFile);bindTableEvents();loadCategoryDictionary();loadSourceFiles();});})();